    "conv.convenience.s2": "Caissier",
    "conv.convenience.l3": "Oui, réchauffez-le, s'il vous plaît.",
    "conv.convenience.s3": "Toi",
    "conv.convenience.l4": "Vous avez une carte de fidélité ?",
