    "conv.politeness.l2": "Merci ! (familier)",
    "conv.politeness.s2": "À un ami proche",
    "conv.politeness.l3": "Tu as mangé ? (familier — sert aussi de salutation)",
    "conv.politeness.s3": "Ami",
    "conv.politeness.l4": "Ouais, j'ai mangé. Et toi ?",
    "conv.politeness.s4": "Toi",
    "conv.politeness.l5": "Avez-vous mangé ? (honorifique)",
