    "conv.greetings.l4": "很高興認識你！",
    "conv.greetings.s4": "Minsu",
    "conv.greetings.l5": "我也很高興認識你。",
    "conv.greetings.s5": "Emma",
    "conv.greetings.k0": "你好（任何時段都能用）",
    "conv.greetings.k1": "很高興認識你",
